#include <bits/stdc++.h>
using namespace std;

long long modExp(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m;
    cin >> n >> m;
    long long k = n * m;
    long long l, r;
    cin >> l >> r;
    long long len = r - l + 1;
    const long long mod = 998244353;

    if (k % 2 == 1) {
        cout << modExp(len, n * m, mod) << "\n";
    } else {
        long long ans = (modExp(len, k, mod) + modExp(len % 2, k, mod)) % mod;
        long long inv2 = modExp(2, mod - 2, mod);
        ans = (ans * inv2) % mod;
        cout << ans << "\n";
    }
    return 0;
}
